//////////////////////////////////////////////////////////////////////////
/// has_common_element
///
/// Specification: returns true iff there exist indices `i` in `0..a.len()`
/// and `j` in `0..b.len()` such that `a[i] == b[j]`.
//////////////////////////////////////////////////////////////////////////
#[verifier::opaque]
fn has_common_element(a: &[i32], b: &[i32]) -> bool {
    ensures!(
        result <==>
        // ∃i < a.len(), ∃j < b.len(): a[i] == b[j]
        (|_a: Seq<i32>, _b: Seq<i32>| {
            exists |i: usize|
                i < Seq::len(_a)
                && exists |j: usize|
                    j < Seq::len(_b)
                    && Seq::index(_a, i) == Seq::index(_b, j)
        })(seq(a), seq(b))
    );
    a.iter().any(|x| b.contains(x))
}

